import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_H": 1, "BLOCK_W": 32},
        ),
    ],
    key=["OH", "OW"],
)
@triton.jit
def _maxpool2d_kernel(
    x_ptr,
    out_ptr,
    H,
    W,
    OH,
    OW,
    BLOCK_H: tl.constexpr,
    BLOCK_W: tl.constexpr,
    KERNEL_SIZE: tl.constexpr,
    STRIDE: tl.constexpr,
    PADDING: tl.constexpr,
    DILATION: tl.constexpr,
    IS_BF16: tl.constexpr,
):
    pid_bc = tl.program_id(0)
    pid_oh = tl.program_id(1)
    pid_ow = tl.program_id(2)

    x_base = x_ptr + pid_bc.to(tl.int64) * H * W
    out_base = out_ptr + pid_bc.to(tl.int64) * OH * OW

    oh_offsets = pid_oh * BLOCK_H + tl.arange(0, BLOCK_H)
    ow_offsets = pid_ow * BLOCK_W + tl.arange(0, BLOCK_W)

    max_vals = tl.full((BLOCK_H, BLOCK_W), float("-inf"), dtype=tl.float32)

    for kh in range(KERNEL_SIZE):
        ih = oh_offsets * STRIDE - PADDING + kh * DILATION
        valid_h = (ih >= 0) & (ih < H) & (oh_offsets < OH)
        for kw in range(KERNEL_SIZE):
            iw = ow_offsets * STRIDE - PADDING + kw * DILATION
            valid_w = (iw >= 0) & (iw < W) & (ow_offsets < OW)
            mask = valid_h[:, None] & valid_w[None, :]
            ptrs = x_base + ih[:, None] * W + iw[None, :]
            vals = tl.load(ptrs, mask=mask, other=float("-inf")).to(tl.float32)
            max_vals = tl.maximum(max_vals, vals)

    out_mask = (oh_offsets < OH)[:, None] & (ow_offsets < OW)[None, :]
    out_ptrs = out_base + oh_offsets[:, None] * OW + ow_offsets[None, :]
    if IS_BF16:
        tl.store(out_ptrs, max_vals.to(tl.bfloat16), mask=out_mask)
    else:
        tl.store(out_ptrs, max_vals, mask=out_mask)


def maxpool2d(x, kernel_size, stride, padding, dilation):
    B, C, H, W = x.shape
    OH = (H + 2 * padding - dilation * (kernel_size - 1) - 1) // stride + 1
    OW = (W + 2 * padding - dilation * (kernel_size - 1) - 1) // stride + 1

    x = x.contiguous()
    out = torch.empty((B, C, OH, OW), device=x.device, dtype=x.dtype)

    is_bf16 = x.dtype == torch.bfloat16

    grid = lambda META: (
        B * C,
        triton.cdiv(OH, META["BLOCK_H"]),
        triton.cdiv(OW, META["BLOCK_W"]),
    )

    _maxpool2d_kernel[grid](
        x,
        out,
        H,
        W,
        OH,
        OW,
        KERNEL_SIZE=kernel_size,
        STRIDE=stride,
        PADDING=padding,
        DILATION=dilation,
        IS_BF16=is_bf16,
    )

    return out


class Model(nn.Module):
    def __init__(self, kernel_size: int, stride: int, padding: int, dilation: int):
        super().__init__()
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return maxpool2d(x, self.kernel_size, self.stride, self.padding, self.dilation)
